209	    void WebSocketTransport::setReadyState(ReadyState readyState)
210	    {
211	        // Lock the _setReadyStateMutex for the duration of this
212	        // method. This ensures that only a single thread runs the
213	        // logic below avoiding concurrent execution of the
214	        // close callback my multiple threads at the same time.
215	        std::lock_guard<std::mutex> lock(_setReadyStateMutex);
216	
217	        // No state change, return
218	        if (_readyState == readyState) return;
219	
220	        if (readyState == ReadyState::CLOSED)
221	        {
222	            if (_onCloseCallback)
223	            {
224	                _onCloseCallback(_closeCode, getCloseReason(), _closeWireSize, _closeRemote);
225	            }
226	            setCloseReason(WebSocketCloseConstants::kInternalErrorMessage);
227	            _closeCode = WebSocketCloseConstants::kInternalErrorCode;
228	            _closeWireSize = 0;
229	            _closeRemote = false;
230	        }
231	        else if (readyState == ReadyState::OPEN)
232	        {
233	            initTimePointsAfterConnect();
234	            _pongReceived = false;
235	        }
236	
237	        _readyState = readyState;
238	    }
