310	    bool WebSocketTransport::closingDelayExceeded()
311	    {
312	        std::lock_guard<std::mutex> lock(_closingTimePointMutex);
313	        auto now = std::chrono::steady_clock::now();
314	        return now - _closingTimePoint > std::chrono::milliseconds(kClosingMaximumWaitingDelayInMs);
315	    }
316	
317	    WebSocketTransport::PollResult WebSocketTransport::poll()
318	    {
319	        if (_readyState == ReadyState::OPEN)
320	        {
321	            if (pingIntervalExceeded())
322	            {
323	                // If it is not a 'ping' message of ping type, there is no need to judge whether
324	                // pong will receive it
325	                if (_pingType == SendMessageKind::Ping && !_pongReceived)
326	                {
327	                    // ping response (PONG) exceeds the maximum delay, close the connection
328	                    close(WebSocketCloseConstants::kInternalErrorCode,
329	                          WebSocketCloseConstants::kPingTimeoutMessage);
330	                }
331	                else
332	                {
333	                    sendHeartBeat(_pingType);
334	                }
335	            }
336	        }
337	
338	        // No timeout if state is not OPEN, otherwise computed
339	        // pingIntervalOrTimeoutGCD (equals to -1 if no ping and no ping timeout are set)
340	        int lastingTimeoutDelayInMs = (_readyState != ReadyState::OPEN) ? 0 : _pingIntervalSecs;
341	
342	        if (_pingIntervalSecs > 0)
343	        {
344	            // compute lasting delay to wait for next ping / timeout, if at least one set
345	            auto now = std::chrono::steady_clock::now();
346	            int timeSinceLastPingMs = (int) std::chrono::duration_cast<std::chrono::milliseconds>(
347	                                          now - _lastSendPingTimePoint)
348	                                          .count();
349	            lastingTimeoutDelayInMs = (1000 * _pingIntervalSecs) - timeSinceLastPingMs;
350	        }
351	
352	        // The platform may not have select interrupt capabilities, so wait with a small timeout
353	        if (lastingTimeoutDelayInMs <= 0 && !_socket->isWakeUpFromPollSupported())
354	        {
355	            lastingTimeoutDelayInMs = 20;
356	        }
357	
358	        // If we are requesting a cancellation, pass in a positive and small timeout
359	        // to never poll forever without a timeout.
360	        if (_requestInitCancellation)
361	        {
362	            lastingTimeoutDelayInMs = 100;
363	        }
364	
365	        // poll the socket
366	        PollResultType pollResult = _socket->isReadyToRead(lastingTimeoutDelayInMs);
367	
368	        // Make sure we send all the buffered data
369	        // there can be a lot of it for large messages.
370	        if (pollResult == PollResultType::SendRequest)
371	        {
372	            if (!flushSendBuffer())
373	            {
374	                return PollResult::CannotFlushSendBuffer;
375	            }
376	        }
377	        else if (pollResult == PollResultType::ReadyForRead)
378	        {
379	            if (!receiveFromSocket())
380	            {
381	                return PollResult::AbnormalClose;
382	            }
383	        }
384	        else if (pollResult == PollResultType::Error)
385	        {
386	            closeSocket();
387	        }
388	        else if (pollResult == PollResultType::CloseRequest)
389	        {
390	            closeSocket();
391	        }
392	
393	        if (_readyState == ReadyState::CLOSING && closingDelayExceeded())
394	        {
395	            _rxbuf.clear();
396	            // close code and reason were set when calling close()
397	            closeSocket();
398	            setReadyState(ReadyState::CLOSED);
399	        }
400	
401	        return PollResult::Succeeded;
402	    }
