834	
835	    WebSocketSendInfo WebSocketTransport::sendData(wsheader_type::opcode_type type,
836	                                                   const IXWebSocketSendData& message,
837	                                                   bool compress,
838	                                                   const OnProgressCallback& onProgressCallback)
839	    {
840	        if (_readyState != ReadyState::OPEN && _readyState != ReadyState::CLOSING)
841	        {
842	            return WebSocketSendInfo(false);
843	        }
844	
845	        size_t payloadSize = message.size();
846	        size_t wireSize = message.size();
847	        bool compressionError = false;
848	
849	        auto message_begin = message.cbegin();
850	        auto message_end = message.cend();
851	
852	        if (compress)
853	        {
854	            if (!_perMessageDeflate->compress(message, _compressedMessage))
855	            {
856	                bool success = false;
857	                compressionError = true;
858	                payloadSize = 0;
859	                wireSize = 0;
860	                return WebSocketSendInfo(success, compressionError, payloadSize, wireSize);
861	            }
862	            compressionError = false;
863	            wireSize = _compressedMessage.size();
864	
865	            IXWebSocketSendData compressedSendData(_compressedMessage);
866	            message_begin = compressedSendData.cbegin();
867	            message_end = compressedSendData.cend();
868	        }
869	
870	        {
871	            std::lock_guard<std::mutex> lock(_txbufMutex);
872	            _txbuf.reserve(wireSize);
873	        }
874	
875	        bool success = true;
876	
877	        // Common case for most message. No fragmentation required.
878	        if (wireSize < kChunkSize)
879	        {
880	            success = sendFragment(type, true, message_begin, message_end, compress);
881	
882	            if (onProgressCallback)
883	            {
884	                onProgressCallback(0, 1);
885	            }
886	        }
887	        else
888	        {
889	            //
890	            // Large messages need to be fragmented
891	            //
892	            // Rules:
893	            // First message needs to specify a proper type (BINARY or TEXT)
894	            // Intermediary and last messages need to be of type CONTINUATION
895	            // Last message must set the fin byte.
896	            //
897	            auto steps = wireSize / kChunkSize;
898	
899	            auto begin = message_begin;
900	            auto end = message_end;
901	
902	            for (uint64_t i = 0; i < steps; ++i)
903	            {
904	                bool firstStep = i == 0;
905	                bool lastStep = (i + 1) == steps;
906	                bool fin = lastStep;
907	
908	                end = begin + kChunkSize;
909	                if (lastStep)
910	                {
911	                    end = message_end;
912	                }
913	
914	                auto opcodeType = type;
915	                if (!firstStep)
916	                {
917	                    opcodeType = wsheader_type::CONTINUATION;
918	                }
919	
920	                // Send message
921	                if (!sendFragment(opcodeType, fin, begin, end, compress))
922	                {
923	                    return WebSocketSendInfo(false);
924	                }
925	
926	                if (onProgressCallback && !onProgressCallback((int) i, (int) steps))
927	                {
928	                    break;
929	                }
930	
931	                begin += kChunkSize;
932	            }
933	        }
934	
935	        // Request to flush the send buffer on the background thread if it isn't empty
936	        if (!isSendBufferEmpty())
937	        {
938	            wakeUpFromPoll(SelectInterrupt::kSendRequest);
939	
940	            // FIXME: we should have a timeout when sending large messages: see #131
941	            if (_blockingSend && !flushSendBuffer())
942	            {
943	                success = false;
944	            }
945	        }
946	
947	        return WebSocketSendInfo(success, compressionError, payloadSize, wireSize);
948	    }
949	
950	    template<class Iterator>
951	    bool WebSocketTransport::sendFragment(wsheader_type::opcode_type type,
952	                                          bool fin,
953	                                          Iterator message_begin,
954	                                          Iterator message_end,
955	                                          bool compress)
956	    {
957	        uint64_t message_size = static_cast<uint64_t>(message_end - message_begin);
958	
959	        unsigned x = getRandomUnsigned();
960	        uint8_t masking_key[4] = {};
961	        masking_key[0] = (x >> 24);
962	        masking_key[1] = (x >> 16) & 0xff;
963	        masking_key[2] = (x >> 8) & 0xff;
964	        masking_key[3] = (x) &0xff;
965	
966	        std::vector<uint8_t> header;
967	        header.assign(2 + (message_size >= 126 ? 2 : 0) + (message_size >= 65536 ? 6 : 0) +
968	                          (_useMask ? 4 : 0),
969	                      0);
970	        header[0] = type;
971	
972	        // The fin bit indicate that this is the last fragment. Fin is French for end.
973	        if (fin)
974	        {
975	            header[0] |= 0x80;
976	        }
977	
978	        // The rsv1 bit indicate that the frame is compressed
979	        // continuation opcodes should not set it. Autobahn 12.2.10 and others 12.X
980	        if (compress && type != wsheader_type::CONTINUATION)
981	        {
982	            header[0] |= 0x40;
983	        }
984	
985	        if (message_size < 126)
986	        {
987	            header[1] = (message_size & 0xff) | (_useMask ? 0x80 : 0);
988	
989	            if (_useMask)
990	            {
991	                header[2] = masking_key[0];
992	                header[3] = masking_key[1];
993	                header[4] = masking_key[2];
994	                header[5] = masking_key[3];
995	            }
996	        }
997	        else if (message_size < 65536)
998	        {
999	            header[1] = 126 | (_useMask ? 0x80 : 0);
1000	            header[2] = (message_size >> 8) & 0xff;
1001	            header[3] = (message_size >> 0) & 0xff;
1002	
1003	            if (_useMask)
1004	            {
1005	                header[4] = masking_key[0];
1006	                header[5] = masking_key[1];
1007	                header[6] = masking_key[2];
1008	                header[7] = masking_key[3];
1009	            }
1010	        }
1011	        else
1012	        { // TODO: run coverage testing here
1013	            header[1] = 127 | (_useMask ? 0x80 : 0);
1014	            header[2] = (message_size >> 56) & 0xff;
1015	            header[3] = (message_size >> 48) & 0xff;
1016	            header[4] = (message_size >> 40) & 0xff;
1017	            header[5] = (message_size >> 32) & 0xff;
1018	            header[6] = (message_size >> 24) & 0xff;
1019	            header[7] = (message_size >> 16) & 0xff;
1020	            header[8] = (message_size >> 8) & 0xff;
1021	            header[9] = (message_size >> 0) & 0xff;
1022	
1023	            if (_useMask)
1024	            {
1025	                header[10] = masking_key[0];
1026	                header[11] = masking_key[1];
1027	                header[12] = masking_key[2];
1028	                header[13] = masking_key[3];
1029	            }
1030	        }
1031	
1032	        // _txbuf will keep growing until it can be transmitted over the socket:
1033	        appendToSendBuffer(header, message_begin, message_end, message_size, masking_key);
1034	
1035	        // Now actually send this data
1036	        return sendOnSocket();
1037	    }
