1069	    bool WebSocketTransport::sendOnSocket()
1070	    {
1071	        std::lock_guard<std::mutex> lock(_txbufMutex);
1072	
1073	        while (_txbuf.size())
1074	        {
1075	            std::ptrdiff_t ret = 0;
1076	            {
1077	                std::lock_guard<std::mutex> lock(_socketMutex);
1078	                ret = _socket->send((char*) &_txbuf[0], _txbuf.size());
1079	            }
1080	
1081	            if (ret < 0 && Socket::isWaitNeeded())
1082	            {
1083	                break;
1084	            }
1085	            else if (ret <= 0)
1086	            {
1087	                closeSocket();
1088	                if (_readyState != ReadyState::CLOSING)
1089	                {
1090	                    setReadyState(ReadyState::CLOSED);
1091	                }
1092	                return false;
1093	            }
1094	            else
1095	            {
1096	                _txbuf.erase(_txbuf.begin(), _txbuf.begin() + ret);
1097	            }
1098	        }
1099	
1100	        return true;
1101	    }
1102	
1103	    bool WebSocketTransport::receiveFromSocket()
1104	    {
1105	        while (true)
1106	        {
1107	            // If _rxbufWanted isn't set, don't attempt to read more than kChunkSize
1108	            // into _rxbuf. If a client is sending frames faster than they can be
1109	            // processed this would otherwise bloat _rxbuf and further introduce
1110	            // unnecessary processing overhead due to .erase() in dispatch().
1111	            //
1112	            // Further, not reading everything from the socket will eventually
1113	            // result in back pressure for the client.
1114	            if (_rxbufWanted == 0 && _rxbuf.size() >= kChunkSize) break;
1115	
1116	            // There's also no point in reading more bytes than needed.
1117	            if (_rxbufWanted > 0 && _rxbuf.size() >= _rxbufWanted) break;
1118	
1119	            std::ptrdiff_t ret = _socket->recv((char*) &_readbuf[0], _readbuf.size());
1120	
1121	            if (ret < 0 && Socket::isWaitNeeded())
1122	            {
1123	                break;
1124	            }
1125	            else if (ret <= 0)
1126	            {
1127	                // if there are received data pending to be processed, then delay the abnormal
1128	                // closure to after dispatch (other close code/reason could be read from the
1129	                // buffer)
1130	
1131	                closeSocket();
1132	                return false;
1133	            }
1134	            else
1135	            {
1136	                _rxbuf.insert(_rxbuf.end(), _readbuf.begin(), _readbuf.begin() + ret);
1137	            }
1138	        }
1139	
1140	        return true;
1141	    }
