1143	    void WebSocketTransport::sendCloseFrame(uint16_t code, const std::string& reason)
1144	    {
1145	        bool compress = false;
1146	
1147	        // if a status is set/was read
1148	        if (code != WebSocketCloseConstants::kNoStatusCodeErrorCode)
1149	        {
1150	            // See list of close events here:
1151	            // https://developer.mozilla.org/en-US/docs/Web/API/CloseEvent
1152	            std::string closure {(char) (code >> 8), (char) (code & 0xff)};
1153	
1154	            // copy reason after code
1155	            closure.append(reason);
1156	
1157	            sendData(wsheader_type::CLOSE, closure, compress);
1158	        }
1159	        else
1160	        {
1161	            // no close code/reason set
1162	            sendData(wsheader_type::CLOSE, std::string(""), compress);
1163	        }
1164	    }
