1193	
1194	    void WebSocketTransport::close(uint16_t code,
1195	                                   const std::string& reason,
1196	                                   size_t closeWireSize,
1197	                                   bool remote)
1198	    {
1199	        _requestInitCancellation = true;
1200	
1201	        if (_readyState == ReadyState::CLOSING || _readyState == ReadyState::CLOSED)
1202	        {
1203	            // Wake up the socket polling thread, as
1204	            // Socket::isReadyToRead() might be still waiting the
1205	            // interrupt event to happen.
1206	            bool wakeUpPoll = false;
1207	            {
1208	              std::lock_guard<std::mutex> lock(_socketMutex);
1209	              wakeUpPoll = (_socket && _socket->isWakeUpFromPollSupported());
1210	            }
1211	            if (wakeUpPoll)
1212	            {
1213	                wakeUpFromPoll(SelectInterrupt::kCloseRequest);
1214	            }
1215	            return;
1216	        }
1217	
1218	        if (closeWireSize == 0)
1219	        {
1220	            closeWireSize = reason.size();
1221	        }
1222	
1223	        setCloseReason(reason);
1224	        _closeCode = code;
1225	        _closeWireSize = closeWireSize;
1226	        _closeRemote = remote;
1227	
1228	        {
1229	            std::lock_guard<std::mutex> lock(_closingTimePointMutex);
1230	            _closingTimePoint = std::chrono::steady_clock::now();
1231	        }
1232	        setReadyState(ReadyState::CLOSING);
1233	
1234	        sendCloseFrame(code, reason);
1235	
1236	        // wake up the poll, but do not close yet
1237	        wakeUpFromPoll(SelectInterrupt::kSendRequest);
1238	    }
