1245	
1246	    bool WebSocketTransport::flushSendBuffer()
1247	    {
1248	        auto start = std::chrono::steady_clock::now();
1249	
1250	        // timeoutMs tracks how long to wait before forcefully
1251	        // closing the socket when sending runs into a timeout.
1252	        std::chrono::seconds timeoutSecs(0);
1253	        if (_sendTimeoutSecs > 0)
1254	        {
1255	            timeoutSecs = std::chrono::seconds(_sendTimeoutSecs);
1256	        }
1257	        else if (_pingIntervalSecs > 0)
1258	        {
1259	            // If a pingInterval is set, use it as a timeout because if we cannot
1260	            // send out any data for pingInterval seconds, we may as well disconnet
1261	            // the client.
1262	            timeoutSecs = std::chrono::seconds(_pingIntervalSecs);
1263	        }
1264	
1265	        while (!isSendBufferEmpty() && !_requestInitCancellation)
1266	        {
1267	            // Wait with a 10ms timeout until the socket is ready to write.
1268	            // This way we are not busy looping
1269	            PollResultType result = _socket->isReadyToWrite(10);
1270	
1271	            if (result == PollResultType::Error)
1272	            {
1273	                closeSocket();
1274	                setReadyState(ReadyState::CLOSED);
1275	                return false;
1276	            }
1277	            else if (result == PollResultType::ReadyForWrite)
1278	            {
1279	                if (!sendOnSocket())
1280	                {
1281	                    return false;
1282	                }
1283	            }
1284	            else if (result == PollResultType::Timeout && timeoutSecs.count() > 0)
1285	            {
1286	                auto now = std::chrono::steady_clock::now();
1287	                // Timeout error and exceeded the allocated timeout: Treat
1288	                // as abnormal close and use "Send Timeout" for the reason.
1289	                if (now > start + timeoutSecs)
1290	                {
1291	                    closeSocketAndSwitchToClosedState(WebSocketCloseConstants::kAbnormalCloseCode,
1292	                                                      WebSocketCloseConstants::kSendTimeoutMessage,
1293	                                                      0,
1294	                                                      false);
1295	                    return false;
1296	                }
1297	            }
1298	        }
1299	
1300	        return true;
1301	    }
1302	
1303	    void WebSocketTransport::setCloseReason(const std::string& reason)
1304	    {
