317	    {
318	        using millis = std::chrono::duration<double, std::milli>;
319	
320	        uint32_t retries = 0;
321	        millis duration(0);
322	
323	        // Try to connect perpetually
324	        while (true)
325	        {
326	            if (isConnected() || isClosing() || _stop)
327	            {
328	                break;
329	            }
330	
331	            if (!firstConnectionAttempt && !_automaticReconnection)
332	            {
333	                // Do not attempt to reconnect
334	                break;
335	            }
336	
337	            firstConnectionAttempt = false;
338	
339	            // Only sleep if we are retrying
340	            if (duration.count() > 0)
341	            {
342	                std::unique_lock<std::mutex> lock(_sleepMutex);
343	                _sleepCondition.wait_for(lock, duration);
344	            }
345	
346	            if (_stop)
347	            {
348	                break;
349	            }
350	
351	            // Try to connect synchronously
352	            ix::WebSocketInitResult status = connect(_handshakeTimeoutSecs);
353	
354	            if (!status.success)
355	            {
356	                WebSocketErrorInfo connectErr;
357	
358	                if (_automaticReconnection)
359	                {
360	                    duration =
361	                        millis(calculateRetryWaitMilliseconds(retries++,
362	                                                              _maxWaitBetweenReconnectionRetries,
363	                                                              _minWaitBetweenReconnectionRetries));
364	
365	                    connectErr.wait_time = duration.count();
366	                    connectErr.retries = retries;
367	                }
368	
369	                connectErr.reason = status.errorStr;
370	                connectErr.http_status = status.http_status;
371	
372	                _onMessageCallback(ix::make_unique<WebSocketMessage>(WebSocketMessageType::Error,
373	                                                                     emptyMsg,
374	                                                                     0,
375	                                                                     connectErr,
376	                                                                     WebSocketOpenInfo(),
377	                                                                     WebSocketCloseInfo()));
378	            }
379	        }
380	    }
