536	    WebSocketSendInfo WebSocket::ping(const std::string& text, SendMessageKind pingType)
537	    {
538	        // Standard limit ping message size
539	        constexpr size_t pingMaxPayloadSize = 125;
540	        if (text.size() > pingMaxPayloadSize) return WebSocketSendInfo(false);
541	
542	        return sendMessage(text, pingType);
543	    }
544	
545	    WebSocketSendInfo WebSocket::sendMessage(const IXWebSocketSendData& message,
546	                                             SendMessageKind sendMessageKind,
547	                                             const OnProgressCallback& onProgressCallback)
548	    {
549	        if (!isConnected()) return WebSocketSendInfo(false);
550	
551	        //
552	        // It is OK to read and write on the same socket in 2 different threads.
553	        // https://stackoverflow.com/questions/1981372/are-parallel-calls-to-send-recv-on-the-same-socket-valid
554	        //
555	        // This makes it so that messages are sent right away, and we dont need
556	        // a timeout while we poll to keep wake ups to a minimum (which helps
557	        // with battery life), and use the system select call to notify us when
558	        // incoming messages are arriving / there's data to be received.
559	        //
560	        std::lock_guard<std::mutex> lock(_writeMutex);
561	        WebSocketSendInfo webSocketSendInfo;
562	
563	        switch (sendMessageKind)
564	        {
565	            case SendMessageKind::Text:
566	            {
567	                webSocketSendInfo = _ws.sendText(message, onProgressCallback);
568	            }
569	            break;
570	
571	            case SendMessageKind::Binary:
572	            {
573	                webSocketSendInfo = _ws.sendBinary(message, onProgressCallback);
574	            }
575	            break;
576	
577	            case SendMessageKind::Ping:
578	            {
579	                webSocketSendInfo = _ws.sendPing(message);
580	            }
581	            break;
582	        }
583	
584	        WebSocket::invokeTrafficTrackerCallback(webSocketSendInfo.wireSize, false);
585	
586	        return webSocketSendInfo;
587	    }
