//
// Raw-socket verification tests for fragmented message reception.
// Drives crafted frames into ix::WebSocket (client) and ix::WebSocketServer
// and checks the emitted callbacks.
//

#include <ixwebsocket/IXWebSocket.h>
#include <ixwebsocket/IXWebSocketServer.h>
#include <ixwebsocket/IXWebSocketHandshakeKeyGen.h>
#include <ixwebsocket/IXWebSocketPerMessageDeflateCodec.h>

#include <arpa/inet.h>
#include <chrono>
#include <cstring>
#include <iostream>
#include <mutex>
#include <netinet/in.h>
#include <netinet/tcp.h>
#include <string>
#include <sys/socket.h>
#include <thread>
#include <unistd.h>
#include <vector>

static int g_failures = 0;
static int g_checks = 0;

#define CHECK(cond, name)                                                                          \
    do                                                                                             \
    {                                                                                              \
        ++g_checks;                                                                                \
        if (!(cond))                                                                               \
        {                                                                                          \
            ++g_failures;                                                                          \
            std::cout << "FAIL: " << name << " (line " << __LINE__ << ")" << std::endl;            \
        }                                                                                          \
    } while (0)

// ---------------------------------------------------------------------------
// Raw websocket peer helpers
// ---------------------------------------------------------------------------

static bool readN(int fd, uint8_t* buf, size_t n, int timeoutMs = 3000)
{
    size_t got = 0;
    while (got < n)
    {
        fd_set rfds;
        FD_ZERO(&rfds);
        FD_SET(fd, &rfds);
        struct timeval tv;
        tv.tv_sec = timeoutMs / 1000;
        tv.tv_usec = (timeoutMs % 1000) * 1000;
        int r = select(fd + 1, &rfds, nullptr, nullptr, &tv);
        if (r <= 0) return false;
        ssize_t ret = recv(fd, buf + got, n - got, 0);
        if (ret <= 0) return false;
        got += (size_t) ret;
    }
    return true;
}

static bool writeAll(int fd, const uint8_t* buf, size_t n)
{
    size_t sent = 0;
    while (sent < n)
    {
        ssize_t ret = send(fd, buf + sent, n - sent, MSG_NOSIGNAL);
        if (ret <= 0) return false;
        sent += (size_t) ret;
    }
    return true;
}

static bool writeAll(int fd, const std::string& s)
{
    return writeAll(fd, (const uint8_t*) s.data(), s.size());
}

struct RawFrame
{
    bool fin = false;
    bool rsv1 = false;
    int opcode = 0;
    std::string payload;
};

// Build a serialized frame. mask=true for client->server traffic.
static std::string buildFrame(bool fin,
                              bool rsv1,
                              int opcode,
                              const std::string& payload,
                              bool mask)
{
    std::string out;
    uint8_t b0 = (uint8_t) opcode;
    if (fin) b0 |= 0x80;
    if (rsv1) b0 |= 0x40;
    out += (char) b0;

    uint8_t maskBit = mask ? 0x80 : 0;
    size_t n = payload.size();
    if (n < 126)
    {
        out += (char) (maskBit | (uint8_t) n);
    }
    else if (n < 65536)
    {
        out += (char) (maskBit | 126);
        out += (char) ((n >> 8) & 0xff);
        out += (char) (n & 0xff);
    }
    else
    {
        out += (char) (maskBit | 127);
        for (int i = 7; i >= 0; --i)
            out += (char) ((n >> (8 * i)) & 0xff);
    }

    if (mask)
    {
        uint8_t key[4] = {0x12, 0x34, 0x56, 0x78};
        out.append((char*) key, 4);
        for (size_t i = 0; i < n; ++i)
            out += (char) (payload[i] ^ key[i & 3]);
    }
    else
    {
        out += payload;
    }
    return out;
}

static bool sendFrame(int fd, bool fin, bool rsv1, int opcode, const std::string& payload, bool mask)
{
    return writeAll(fd, buildFrame(fin, rsv1, opcode, payload, mask));
}

static bool recvFrame(int fd, RawFrame& frame, int timeoutMs = 3000)
{
    uint8_t hdr[2];
    if (!readN(fd, hdr, 2, timeoutMs)) return false;
    frame.fin = (hdr[0] & 0x80) != 0;
    frame.rsv1 = (hdr[0] & 0x40) != 0;
    frame.opcode = hdr[0] & 0x0f;
    bool masked = (hdr[1] & 0x80) != 0;
    uint64_t n = hdr[1] & 0x7f;
    if (n == 126)
    {
        uint8_t ext[2];
        if (!readN(fd, ext, 2, timeoutMs)) return false;
        n = ((uint64_t) ext[0] << 8) | ext[1];
    }
    else if (n == 127)
    {
        uint8_t ext[8];
        if (!readN(fd, ext, 8, timeoutMs)) return false;
        n = 0;
        for (int i = 0; i < 8; ++i)
            n = (n << 8) | ext[i];
    }
    uint8_t key[4] = {0, 0, 0, 0};
    if (masked)
    {
        if (!readN(fd, key, 4, timeoutMs)) return false;
    }
    frame.payload.assign(n, '\0');
    if (n > 0 && !readN(fd, (uint8_t*) &frame.payload[0], (size_t) n, timeoutMs)) return false;
    if (masked)
    {
        for (uint64_t i = 0; i < n; ++i)
            frame.payload[i] = (char) (frame.payload[i] ^ key[i & 3]);
    }
    return true;
}

static std::string computeAcceptKey(const std::string& clientKey)
{
    char output[28];
    WebSocketHandshakeKeyGen::generate(clientKey, output);
    return std::string(output, 28);
}

// Read an HTTP request/response head (terminated by \r\n\r\n)
static std::string readHttpHead(int fd)
{
    std::string data;
    char c;
    while (data.find("\r\n\r\n") == std::string::npos)
    {
        if (!readN(fd, (uint8_t*) &c, 1, 5000)) return "";
        data += c;
        if (data.size() > 65536) return "";
    }
    return data;
}

static std::string headerValue(const std::string& head, const std::string& name)
{
    std::string lower;
    for (char c : head)
        lower += (char) tolower(c);
    std::string needle;
    for (char c : name)
        needle += (char) tolower(c);
    auto pos = lower.find("\r\n" + needle + ":");
    if (pos == std::string::npos) return "";
    pos += 2 + needle.size() + 1;
    while (pos < head.size() && (head[pos] == ' ' || head[pos] == '\t'))
        ++pos;
    auto end = head.find("\r\n", pos);
    return head.substr(pos, end - pos);
}

// Raw server: listen on port, accept one connection, complete the handshake.
// If deflate is requested by the client and allowDeflate, negotiate it.
static int rawListen(uint16_t port)
{
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    int one = 1;
    setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    addr.sin_port = htons(port);
    if (bind(fd, (struct sockaddr*) &addr, sizeof(addr)) != 0) return -1;
    if (listen(fd, 4) != 0) return -1;
    return fd;
}

static int rawAccept(int listenFd, bool allowDeflate, bool* deflateNegotiated = nullptr)
{
    int fd = accept(listenFd, nullptr, nullptr);
    if (fd < 0) return -1;
    std::string head = readHttpHead(fd);
    if (head.empty())
    {
        close(fd);
        return -1;
    }
    std::string key = headerValue(head, "Sec-WebSocket-Key");
    bool wantsDeflate = headerValue(head, "Sec-WebSocket-Extensions").find("permessage-deflate") !=
                        std::string::npos;
    std::string resp = "HTTP/1.1 101 Switching Protocols\r\n"
                       "Upgrade: websocket\r\n"
                       "Connection: Upgrade\r\n"
                       "Sec-WebSocket-Accept: " +
                       computeAcceptKey(key) + "\r\n";
    bool negotiated = allowDeflate && wantsDeflate;
    if (negotiated)
    {
        resp += "Sec-WebSocket-Extensions: permessage-deflate\r\n";
    }
    resp += "\r\n";
    if (!writeAll(fd, resp))
    {
        close(fd);
        return -1;
    }
    if (deflateNegotiated) *deflateNegotiated = negotiated;
    return fd;
}

// Raw client: connect and complete the handshake as a client.
static int rawClientConnect(uint16_t port, bool offerDeflate)
{
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    addr.sin_port = htons(port);
    if (connect(fd, (struct sockaddr*) &addr, sizeof(addr)) != 0)
    {
        close(fd);
        return -1;
    }
    std::string req = "GET / HTTP/1.1\r\n"
                      "Host: 127.0.0.1\r\n"
                      "Upgrade: websocket\r\n"
                      "Connection: Upgrade\r\n"
                      "Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n"
                      "Sec-WebSocket-Version: 13\r\n";
    if (offerDeflate)
    {
        req += "Sec-WebSocket-Extensions: permessage-deflate\r\n";
    }
    req += "\r\n";
    if (!writeAll(fd, req))
    {
        close(fd);
        return -1;
    }
    std::string head = readHttpHead(fd);
    if (head.find("101") == std::string::npos)
    {
        close(fd);
        return -1;
    }
    return fd;
}

// ---------------------------------------------------------------------------
// Event collector for ix::WebSocket / ix::WebSocketServer callbacks
// ---------------------------------------------------------------------------

struct Event
{
    std::string type; // Open, Message, Fragment, Ping, Pong, Close, Error
    std::string str;
    bool binary = false;
    uint16_t code = 0;
    std::string reason;
};

struct Collector
{
    mutable std::mutex mutex;
    std::vector<Event> events;

    void push(const Event& e)
    {
        std::lock_guard<std::mutex> lock(mutex);
        events.push_back(e);
    }

    std::vector<Event> snapshot() const
    {
        std::lock_guard<std::mutex> lock(mutex);
        return events;
    }

    size_t count(const std::string& type) const
    {
        std::lock_guard<std::mutex> lock(mutex);
        size_t n = 0;
        for (auto& e : events)
            if (e.type == type) ++n;
        return n;
    }

    bool waitFor(const std::string& type, size_t n, int timeoutMs = 5000) const
    {
        auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(timeoutMs);
        while (std::chrono::steady_clock::now() < deadline)
        {
            if (count(type) >= n) return true;
            std::this_thread::sleep_for(std::chrono::milliseconds(5));
        }
        return count(type) >= n;
    }

    std::vector<Event> ofType(const std::string& type) const
    {
        std::lock_guard<std::mutex> lock(mutex);
        std::vector<Event> out;
        for (auto& e : events)
            if (e.type == type) out.push_back(e);
        return out;
    }
};

static ix::WebSocketMessageCallback makeCallback(Collector& c)
{
    return [&c](const ix::WebSocketMessagePtr& msg)
    {
        Event e;
        switch (msg->type)
        {
            case ix::WebSocketMessageType::Open: e.type = "Open"; break;
            case ix::WebSocketMessageType::Message: e.type = "Message"; break;
            case ix::WebSocketMessageType::Fragment: e.type = "Fragment"; break;
            case ix::WebSocketMessageType::Ping: e.type = "Ping"; break;
            case ix::WebSocketMessageType::Pong: e.type = "Pong"; break;
            case ix::WebSocketMessageType::Close:
                e.type = "Close";
                e.code = msg->closeInfo.code;
                e.reason = msg->closeInfo.reason;
                break;
            case ix::WebSocketMessageType::Error: e.type = "Error"; break;
        }
        e.str = msg->str;
        e.binary = msg->binary;
        c.push(e);
    };
}

static void sleepMs(int ms)
{
    std::this_thread::sleep_for(std::chrono::milliseconds(ms));
}

// ---------------------------------------------------------------------------
// Test cases: client receiving
// ---------------------------------------------------------------------------

// Fragmented text, utf-8 split across fragments, binary zero bytes,
// empty non-final frame, ping interleaved, split TCP writes.
static void testClientBasicFragmentation()
{
    std::cout << "-- testClientBasicFragmentation" << std::endl;
    int listenFd = rawListen(18081);
    CHECK(listenFd >= 0, "listen");

    Collector c;
    ix::WebSocket ws;
    ws.setUrl("ws://127.0.0.1:18081");
    ws.disableAutomaticReconnection();
    ws.setOnMessageCallback(makeCallback(c));
    ws.start();

    int fd = rawAccept(listenFd, false);
    CHECK(fd >= 0, "accept");
    CHECK(c.waitFor("Open", 1), "open");

    // 1. Fragmented text message in 3 frames, with a ping in the middle.
    sendFrame(fd, false, false, 1, "Hel", false);       // text, non-final
    sendFrame(fd, true, false, 9, "hb", false);        // ping
    sendFrame(fd, false, false, 0, "lo ", false);      // continuation
    sendFrame(fd, true, false, 0, "World", false);     // final continuation

    // The ping should be answered with a pong carrying the same payload.
    RawFrame pong;
    CHECK(recvFrame(fd, pong), "recv pong");
    CHECK(pong.opcode == 0xA && pong.payload == "hb", "pong payload");

    CHECK(c.waitFor("Message", 1), "message 1");
    // 2. UTF-8 multi-byte char split across fragments: "héllo"
    // é = 0xC3 0xA9 ; split between the two bytes.
    sendFrame(fd, false, false, 1, std::string("h\xC3", 2), false);
    sendFrame(fd, true, false, 0, std::string("\xA9" "llo", 4), false);
    CHECK(c.waitFor("Message", 2), "message 2");

    // 3. Binary message with zero bytes across fragments.
    std::string bin1("a\0b", 3);
    std::string bin2("\0c\0", 3);
    sendFrame(fd, false, false, 2, bin1, false);
    sendFrame(fd, true, false, 0, bin2, false);
    CHECK(c.waitFor("Message", 3), "message 3");

    // 4. Empty non-final text frame: message is still in progress.
    sendFrame(fd, false, false, 1, "", false); // empty payload, non-final
    sendFrame(fd, true, false, 0, "abc", false);
    CHECK(c.waitFor("Message", 4), "message 4");

    // 5. Frame bytes arriving in separate TCP writes (header split from
    // payload, payload split in two).
    {
        std::string frame = buildFrame(true, false, 1, "split-write", false);
        writeAll(fd, (const uint8_t*) frame.data(), 1);
        sleepMs(30);
        writeAll(fd, (const uint8_t*) frame.data() + 1, 1);
        sleepMs(30);
        writeAll(fd, (const uint8_t*) frame.data() + 2, 5);
        sleepMs(30);
        writeAll(fd, (const uint8_t*) frame.data() + 7, frame.size() - 7);
        CHECK(c.waitFor("Message", 5), "message 5");
    }

    sleepMs(200);
    auto msgs = c.ofType("Message");
    CHECK(msgs.size() == 5, "exactly 5 messages");
    if (msgs.size() >= 5)
    {
        CHECK(msgs[0].str == "Hello World" && !msgs[0].binary, "merged text in order");
        CHECK(msgs[1].str == "h\xC3\xA9" "llo", "utf8 split across fragments");
        CHECK(msgs[2].binary && msgs[2].str.size() == 6 &&
                  msgs[2].str == std::string("a\0b\0c\0", 6),
              "binary zero bytes preserved");
        CHECK(msgs[3].str == "abc", "empty first fragment");
        CHECK(msgs[4].str == "split-write", "split tcp writes");
    }
    // Fragments: 2 for msg1, 1 for msg2, 1 for msg3, 1 for msg4 = 5
    CHECK(c.count("Fragment") == 5, "fragment notifications");
    CHECK(c.count("Ping") == 1, "ping notification");
    auto pings = c.ofType("Ping");
    CHECK(pings.size() == 1 && pings[0].str == "hb", "ping payload");

    // Clean close from the server side
    sendFrame(fd, true, false, 8, std::string("\x03\xE8", 2), false); // 1000
    CHECK(c.waitFor("Close", 1), "close");
    sleepMs(200);
    CHECK(c.count("Close") == 1, "single close notification");
    auto closes = c.ofType("Close");
    CHECK(closes.size() == 1 && closes[0].code == 1000, "close code 1000");

    ws.stop();
    close(fd);
    close(listenFd);
}

// Continuation frame with no message in progress -> 1002, nothing delivered
// afterwards, whether trailing frames arrive in the same or later writes.
static void testClientContinuationOutOfSequence()
{
    std::cout << "-- testClientContinuationOutOfSequence" << std::endl;
    int listenFd = rawListen(18082);
    Collector c;
    ix::WebSocket ws;
    ws.setUrl("ws://127.0.0.1:18082");
    ws.disableAutomaticReconnection();
    ws.setOnMessageCallback(makeCallback(c));
    ws.start();

    int fd = rawAccept(listenFd, false);
    CHECK(c.waitFor("Open", 1), "open");

    // A valid message first, fully delivered before the violation.
    sendFrame(fd, true, false, 1, "before", false);
    CHECK(c.waitFor("Message", 1), "message before violation");

    // Violating continuation frame + a valid message in the SAME write.
    std::string batch = buildFrame(true, false, 0, "bad", false) +
                        buildFrame(true, false, 1, "after", false);
    writeAll(fd, batch);

    CHECK(c.waitFor("Close", 1), "close after violation");
    // Server should receive a close frame with 1002.
    RawFrame closeFrame;
    CHECK(recvFrame(fd, closeFrame), "recv close frame");
    CHECK(closeFrame.opcode == 8, "close opcode");
    uint16_t code = ((uint8_t) closeFrame.payload[0] << 8) | (uint8_t) closeFrame.payload[1];
    CHECK(code == 1002, "close code 1002");
    std::string reason = closeFrame.payload.substr(2);
    CHECK(reason.find("continuation") != std::string::npos, "continuation reason");
    // Echo the close frame back to complete the handshake.
    sendFrame(fd, true, false, 8, closeFrame.payload, false);

    // More data in a LATER write must not be delivered either.
    sleepMs(100);
    sendFrame(fd, true, false, 1, "later", false);
    sleepMs(300);

    auto msgs = c.ofType("Message");
    CHECK(msgs.size() == 1 && msgs[0].str == "before", "only pre-violation message delivered");
    CHECK(c.count("Fragment") == 0, "no fragment from violating frame");
    CHECK(c.count("Close") == 1, "single close");
    auto closes = c.ofType("Close");
    CHECK(closes.size() == 1 && closes[0].code == 1002, "close code 1002 notified");
    CHECK(closes[0].reason.find("continuation") != std::string::npos, "close reason");

    ws.stop();
    close(fd);
    close(listenFd);
}

// New data frame while a fragmented message is in progress -> 1002,
// whether the new frame is final or not. Prior fragments stay notified,
// the interrupted message is never delivered.
static void testClientDataOpcodeOutOfSequence()
{
    std::cout << "-- testClientDataOpcodeOutOfSequence" << std::endl;
    int listenFd = rawListen(18083);
    Collector c;
    ix::WebSocket ws;
    ws.setUrl("ws://127.0.0.1:18083");
    ws.disableAutomaticReconnection();
    ws.setOnMessageCallback(makeCallback(c));
    ws.start();

    int fd = rawAccept(listenFd, false);
    CHECK(c.waitFor("Open", 1), "open");

    sendFrame(fd, false, false, 1, "part1", false); // start a message
    CHECK(c.waitFor("Fragment", 1), "fragment notified");

    // New FINAL text frame while the message is incomplete.
    sendFrame(fd, true, false, 1, "intruder", false);

    RawFrame closeFrame;
    CHECK(recvFrame(fd, closeFrame), "recv close frame");
    CHECK(closeFrame.opcode == 8, "close opcode");
    uint16_t code = ((uint8_t) closeFrame.payload[0] << 8) | (uint8_t) closeFrame.payload[1];
    CHECK(code == 1002, "close code 1002");
    std::string reason = closeFrame.payload.substr(2);
    CHECK(reason.find("data message out of sequence") != std::string::npos, "data reason");
    sendFrame(fd, true, false, 8, closeFrame.payload, false);

    CHECK(c.waitFor("Close", 1), "close notified");
    sleepMs(300);
    CHECK(c.count("Message") == 0, "interrupted message not delivered");
    CHECK(c.count("Fragment") == 1, "only the legal fragment notified");
    CHECK(c.count("Close") == 1, "single close");
    auto closes = c.ofType("Close");
    CHECK(closes.size() == 1 && closes[0].code == 1002, "close code 1002 notified");

    ws.stop();
    close(fd);

    // Variant: the interrupting frame is non-final binary.
    Collector c2;
    ix::WebSocket ws2;
    ws2.setUrl("ws://127.0.0.1:18083");
    ws2.disableAutomaticReconnection();
    ws2.setOnMessageCallback(makeCallback(c2));
    ws2.start();

    int fd2 = rawAccept(listenFd, false);
    CHECK(c2.waitFor("Open", 1), "open 2");
    sendFrame(fd2, false, false, 2, "binpart", false); // binary non-final
    CHECK(c2.waitFor("Fragment", 1), "fragment 2 notified");
    sendFrame(fd2, false, false, 2, "more", false); // new non-final binary frame

    RawFrame closeFrame2;
    CHECK(recvFrame(fd2, closeFrame2), "recv close frame 2");
    CHECK(closeFrame2.opcode == 8, "close opcode 2");
    uint16_t code2 = ((uint8_t) closeFrame2.payload[0] << 8) | (uint8_t) closeFrame2.payload[1];
    CHECK(code2 == 1002, "close code 1002 (2)");
    sendFrame(fd2, true, false, 8, closeFrame2.payload, false);
    CHECK(c2.waitFor("Close", 1), "close notified 2");
    sleepMs(300);
    CHECK(c2.count("Message") == 0, "no message delivered (2)");
    CHECK(c2.count("Fragment") == 1, "one fragment (2)");

    ws2.stop();
    close(fd2);
    close(listenFd);
}

// Empty non-final frame still counts as an open message: a new data frame
// afterwards is a protocol error.
static void testClientEmptyFragmentThenDataFrame()
{
    std::cout << "-- testClientEmptyFragmentThenDataFrame" << std::endl;
    int listenFd = rawListen(18084);
    Collector c;
    ix::WebSocket ws;
    ws.setUrl("ws://127.0.0.1:18084");
    ws.disableAutomaticReconnection();
    ws.setOnMessageCallback(makeCallback(c));
    ws.start();

    int fd = rawAccept(listenFd, false);
    CHECK(c.waitFor("Open", 1), "open");

    sendFrame(fd, false, false, 1, "", false); // empty non-final text frame
    CHECK(c.waitFor("Fragment", 1), "fragment for empty frame");
    sendFrame(fd, true, false, 1, "x", false); // violates: message still open

    RawFrame closeFrame;
    CHECK(recvFrame(fd, closeFrame), "recv close");
    CHECK(closeFrame.opcode == 8, "close opcode");
    uint16_t code = ((uint8_t) closeFrame.payload[0] << 8) | (uint8_t) closeFrame.payload[1];
    CHECK(code == 1002, "1002 after empty fragment + data frame");
    sendFrame(fd, true, false, 8, closeFrame.payload, false);
    CHECK(c.waitFor("Close", 1), "close notified");
    sleepMs(200);
    CHECK(c.count("Message") == 0, "no message");

    ws.stop();
    close(fd);
    close(listenFd);
}

// Peer closes (or vanishes) mid-message: the partial message is dropped.
// Automatic reconnection starts with clean state: no stale content, kind or
// compression attribute; a leading continuation frame on the new connection
// is a fresh 1002 error, and valid messages are delivered normally.
static void testClientReconnectCleanState()
{
    std::cout << "-- testClientReconnectCleanState" << std::endl;
    int listenFd = rawListen(18085);
    Collector c;
    ix::WebSocket ws;
    ws.setUrl("ws://127.0.0.1:18085");
    ws.setOnMessageCallback(makeCallback(c)); // automatic reconnection enabled
    ws.start();

    // Connection 1: start a fragmented message, then drop the TCP connection.
    int fd1 = rawAccept(listenFd, false);
    CHECK(c.waitFor("Open", 1), "open 1");
    sendFrame(fd1, false, false, 1, "OLD-CONTENT", false);
    CHECK(c.waitFor("Fragment", 1), "fragment on conn 1");
    close(fd1); // abnormal close, mid-message

    // Connection 2: first frame is a continuation. It must NOT be appended
    // to the old message; it is a fresh protocol error.
    int fd2 = rawAccept(listenFd, false);
    CHECK(c.waitFor("Open", 2), "open 2");
    sendFrame(fd2, true, false, 0, "-TAIL", false);
    RawFrame closeFrame;
    CHECK(recvFrame(fd2, closeFrame), "recv close on conn 2");
    CHECK(closeFrame.opcode == 8, "close opcode conn 2");
    uint16_t code = ((uint8_t) closeFrame.payload[0] << 8) | (uint8_t) closeFrame.payload[1];
    CHECK(code == 1002, "1002 on conn 2");
    sendFrame(fd2, true, false, 8, closeFrame.payload, false);
    sleepMs(200);
    close(fd2);

    // Connection 3: normal traffic works, both single-frame and fragmented.
    int fd3 = rawAccept(listenFd, false);
    CHECK(c.waitFor("Open", 3), "open 3");
    sendFrame(fd3, true, false, 1, "NEW", false);
    sendFrame(fd3, false, false, 2, std::string("bi", 2), false);
    sendFrame(fd3, true, false, 0, std::string("nary", 4), false);
    CHECK(c.waitFor("Message", 2), "messages on conn 3");
    sleepMs(300);

    auto msgs = c.ofType("Message");
    CHECK(msgs.size() == 2, "exactly 2 messages");
    if (msgs.size() >= 2)
    {
        CHECK(msgs[0].str == "NEW", "no stale content");
        CHECK(msgs[1].str == "binary" && msgs[1].binary, "fragmented binary on new conn");
    }
    // No message may ever contain the old partial content.
    for (auto& m : msgs)
        CHECK(m.str.find("OLD-CONTENT") == std::string::npos, "old content never delivered");

    // One Close notification per connection: conn1 (abnormal), conn2 (1002).
    CHECK(c.count("Close") == 2, "one close per connection");
    auto closes = c.ofType("Close");
    if (closes.size() >= 2)
    {
        CHECK(closes[0].code == 1006, "conn 1 abnormal close");
        CHECK(closes[1].code == 1002, "conn 2 protocol close");
    }

    ws.stop();
    close(fd3);
    close(listenFd);
}

// stop() then start() again on the same object: pending message dropped.
static void testClientStopStart()
{
    std::cout << "-- testClientStopStart" << std::endl;
    int listenFd = rawListen(18086);
    Collector c;
    ix::WebSocket ws;
    ws.setUrl("ws://127.0.0.1:18086");
    ws.setOnMessageCallback(makeCallback(c));
    ws.start();

    int fd1 = rawAccept(listenFd, false);
    CHECK(c.waitFor("Open", 1), "open 1");
    sendFrame(fd1, false, false, 1, "UNFINISHED", false);
    CHECK(c.waitFor("Fragment", 1), "fragment before stop");
    ws.stop();
    close(fd1);

    ws.start();
    int fd2 = rawAccept(listenFd, false);
    CHECK(c.waitFor("Open", 2), "open 2");
    // Complete the "old" message on the new connection: this is a fresh
    // continuation frame with no open message -> 1002, and no merged content.
    sendFrame(fd2, true, false, 0, "-END", false);
    RawFrame closeFrame;
    CHECK(recvFrame(fd2, closeFrame), "recv close");
    CHECK(closeFrame.opcode == 8, "close opcode");
    uint16_t code = ((uint8_t) closeFrame.payload[0] << 8) | (uint8_t) closeFrame.payload[1];
    CHECK(code == 1002, "1002 after restart");
    sendFrame(fd2, true, false, 8, closeFrame.payload, false);
    sleepMs(300);
    CHECK(c.count("Message") == 0, "no merged message after restart");

    ws.stop();
    close(fd2);
    close(listenFd);
}

// Compressed fragmented message with an interleaved control frame.
static void testClientCompressedFragmentation()
{
    std::cout << "-- testClientCompressedFragmentation" << std::endl;
    int listenFd = rawListen(18087);
    Collector c;
    ix::WebSocket ws;
    ws.setUrl("ws://127.0.0.1:18087");
    ws.disableAutomaticReconnection();
    ws.enablePerMessageDeflate();
    ws.setOnMessageCallback(makeCallback(c));
    ws.start();

    bool negotiated = false;
    int fd = rawAccept(listenFd, true, &negotiated);
    CHECK(negotiated, "deflate negotiated");
    CHECK(c.waitFor("Open", 1), "open");

    std::string text =
        "compressed hello world, compressed hello world, compressed hello world!";
    ix::WebSocketPerMessageDeflateCompressor compressor;
    compressor.init(15, false);
    std::string compressed;
    CHECK(compressor.compress(text, compressed), "compress");

    // Split the compressed payload into two frames; rsv1 set on first only.
    size_t half = compressed.size() / 2;
    std::string part1 = compressed.substr(0, half);
    std::string part2 = compressed.substr(half);
    sendFrame(fd, false, true, 1, part1, false);  // text, non-final, rsv1
    sendFrame(fd, true, false, 9, "ctrl", false); // interleaved ping
    sendFrame(fd, true, false, 0, part2, false);  // final continuation

    RawFrame pong;
    CHECK(recvFrame(fd, pong), "recv pong");
    CHECK(pong.opcode == 0xA && pong.payload == "ctrl", "pong payload");

    CHECK(c.waitFor("Message", 1), "compressed message");
    sleepMs(200);
    auto msgs = c.ofType("Message");
    CHECK(msgs.size() == 1 && msgs[0].str == text, "decompressed content");
    CHECK(c.count("Fragment") == 1, "one fragment");
    CHECK(c.count("Ping") == 1, "ping interleaved");

    ws.stop();
    close(fd);
    close(listenFd);
}

// ---------------------------------------------------------------------------
// Test cases: server receiving
// ---------------------------------------------------------------------------

static void testServerSideFragmentation()
{
    std::cout << "-- testServerSideFragmentation" << std::endl;
    Collector c;
    ix::WebSocketServer server(18088, "127.0.0.1");
    server.setOnConnectionCallback(
        [&c](ix::WebSocket* webSocket, std::shared_ptr<ix::ConnectionState>)
        { webSocket->setOnMessageCallback(makeCallback(c)); });
    auto res = server.listen();
    CHECK(res.first, "server listen");
    server.start();

    // 1. A well-formed fragmented masked message from a raw client.
    int fd = rawClientConnect(18088, false);
    CHECK(fd >= 0, "raw client connect");
    CHECK(c.waitFor("Open", 1), "server open");
    sendFrame(fd, false, false, 1, "ser", true);
    sendFrame(fd, true, false, 0, "ver-side", true);
    CHECK(c.waitFor("Message", 1), "server message");
    auto msgs = c.ofType("Message");
    CHECK(msgs.size() == 1 && msgs[0].str == "server-side", "server merged content");
    CHECK(c.count("Fragment") == 1, "server fragment");

    // 2. Protocol violation: new data frame while message in progress.
    sendFrame(fd, false, false, 1, "open-msg", true);
    CHECK(c.waitFor("Fragment", 2), "server fragment 2");
    sendFrame(fd, true, false, 1, "intruder", true);

    // The raw client should receive a 1002 close frame.
    RawFrame closeFrame;
    CHECK(recvFrame(fd, closeFrame), "server close frame");
    CHECK(closeFrame.opcode == 8, "server close opcode");
    uint16_t code = ((uint8_t) closeFrame.payload[0] << 8) | (uint8_t) closeFrame.payload[1];
    CHECK(code == 1002, "server close 1002");
    std::string reason = closeFrame.payload.substr(2);
    CHECK(reason.find("data message out of sequence") != std::string::npos, "server reason");
    sendFrame(fd, true, false, 8, closeFrame.payload, true); // echo close

    CHECK(c.waitFor("Close", 1), "server close notified");
    sleepMs(300);
    CHECK(c.count("Message") == 1, "interrupted message not delivered on server");
    CHECK(c.count("Close") == 1, "single server close");
    auto closes = c.ofType("Close");
    CHECK(closes.size() == 1 && closes[0].code == 1002, "server close code");

    close(fd);

    // 3. New connection: continuation first -> 1002 continuation error.
    int fd2 = rawClientConnect(18088, false);
    CHECK(c.waitFor("Open", 2), "server open 2");
    sendFrame(fd2, true, false, 0, "orphan", true);
    RawFrame closeFrame2;
    CHECK(recvFrame(fd2, closeFrame2), "server close frame 2");
    CHECK(closeFrame2.opcode == 8, "server close opcode 2");
    uint16_t code2 = ((uint8_t) closeFrame2.payload[0] << 8) | (uint8_t) closeFrame2.payload[1];
    CHECK(code2 == 1002, "server close 1002 (2)");
    std::string reason2 = closeFrame2.payload.substr(2);
    CHECK(reason2.find("continuation") != std::string::npos, "server continuation reason");
    sendFrame(fd2, true, false, 8, closeFrame2.payload, true);
    CHECK(c.waitFor("Close", 2), "server close 2 notified");
    sleepMs(200);
    CHECK(c.count("Message") == 1, "still no extra message");

    close(fd2);
    server.stop();
}

int main()
{
    testClientBasicFragmentation();
    testClientContinuationOutOfSequence();
    testClientDataOpcodeOutOfSequence();
    testClientEmptyFragmentThenDataFrame();
    testClientReconnectCleanState();
    testClientStopStart();
    testClientCompressedFragmentation();
    testServerSideFragmentation();

    std::cout << "checks: " << g_checks << ", failures: " << g_failures << std::endl;
    return g_failures == 0 ? 0 : 1;
}

