// Reconnecting with a different compression setup must not be affected by
// the previous connection's compression attribute.
static void testClientReconnectCompressionChange()
{
    std::cout << "-- testClientReconnectCompressionChange" << std::endl;
    int listenFd = rawListen(18089);
    Collector c;
    ix::WebSocket ws;
    ws.setUrl("ws://127.0.0.1:18089");
    ws.enablePerMessageDeflate();
    ws.setOnMessageCallback(makeCallback(c));
    ws.start();

    // Connection 1: compression negotiated; a compressed fragmented message
    // is started (rsv1 first frame) but never finished.
    bool negotiated1 = false;
    int fd1 = rawAccept(listenFd, true, &negotiated1);
    CHECK(negotiated1, "deflate negotiated on conn 1");
    CHECK(c.waitFor("Open", 1), "open 1");
    ix::WebSocketPerMessageDeflateCompressor compressor;
    compressor.init(15, false);
    std::string compressed;
    CHECK(compressor.compress("never finished compressed message", compressed), "compress");
    sendFrame(fd1, false, true, 1, compressed, false); // non-final, rsv1
    CHECK(c.waitFor("Fragment", 1), "compressed fragment");
    close(fd1); // vanish mid-message

    // Connection 2: same object, but the server does not negotiate deflate.
    // Plain uncompressed messages must be delivered as-is.
    int fd2 = rawAccept(listenFd, false);
    CHECK(c.waitFor("Open", 2), "open 2");
    sendFrame(fd2, true, false, 1, "plain", false);
    sendFrame(fd2, false, false, 1, "frag-", false);
    sendFrame(fd2, true, false, 0, "mented", false);
    CHECK(c.waitFor("Message", 2), "plain messages on conn 2");
    sleepMs(300);
    auto msgs = c.ofType("Message");
    CHECK(msgs.size() == 2, "2 messages");
    if (msgs.size() >= 2)
    {
        CHECK(msgs[0].str == "plain", "plain message not decompressed");
        CHECK(msgs[1].str == "frag-mented", "plain fragmented message");
    }

    ws.stop();
    close(fd2);
    close(listenFd);
}

